import networkx as nx
import itertools

# Try to find a sparse 3-connected graph on 15 vertices
# Let's try a construction: start with a cycle, then add a few chords

def is_3_connected(G):
    if G.number_of_nodes() < 4:
        return False
    return nx.node_connectivity(G) >= 3

# Try: cycle + some chords
best = None
best_edges_count = 100

# Try different chord patterns
for offset in range(2, 8):
    G = nx.Graph()
    G.add_nodes_from(range(15))
    for i in range(15):
        G.add_edge(i, (i+1) % 15)
    for i in range(15):
        G.add_edge(i, (i+offset) % 15)
    if is_3_connected(G):
        print(f"Cycle + offset {offset}: {G.number_of_edges()} edges, connectivity {nx.node_connectivity(G)}")

# Try cycle + two offsets
for o1 in range(2, 8):
    for o2 in range(o1+1, 8):
        G = nx.Graph()
        G.add_nodes_from(range(15))
        for i in range(15):
            G.add_edge(i, (i+1) % 15)
        for i in range(15):
            G.add_edge(i, (i+o1) % 15)
        for i in range(15):
            G.add_edge(i, (i+o2) % 15)
        if is_3_connected(G):
            print(f"Cycle + offsets {o1},{o2}: {G.number_of_edges()} edges, connectivity {nx.node_connectivity(G)}")
